.profile-settings {
  max-width: 680px;
  margin: 0 auto;
  padding: 32px 16px 48px;
}

.profile-settings__card {
  padding: 24px 28px;
}

.profile-settings__section {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 24px 0;
  border-bottom: 1px solid var(--g-color-line-generic);
}

.profile-settings__section:first-of-type {
  padding-top: 8px;
}

.profile-settings__field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.profile-settings__row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

@media (max-width: 560px) {
  .profile-settings__row {
    grid-template-columns: 1fr;
  }
  .profile-settings__card {
    padding: 20px 16px;
  }
}

.profile-settings__switch-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.profile-settings__checkbox-hint {
  display: block;
  margin-top: 2px;
}

.profile-settings__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  padding-top: 24px;
}

.profile-settings__status {
  margin-right: auto;
}

